sections.Solution:
```javascript
/**
 * @param {Function} fn
 * @param {number} t
 * @return {Function}
 */
var timeLimit = function(fn, t) {
  return async function(...args) {
    // Timeout promise that rejects once t ms have passed
    const timeout = new Promise((_, reject) =>
      setTimeout(() => reject("Time Limit Exceeded"), t)
    );
    // Whichever settles first decides the outcome
    return Promise.race([fn(...args), timeout]);
  };
};
```

The same idea in Python, for comparison — `asyncio.wait(..., FIRST_COMPLETED)` plays the
role of `Promise.race`:

```python
import asyncio

def timeLimit(fn, t):
    async def wrapper(*args, **kwargs):
        task = asyncio.ensure_future(fn(*args, **kwargs))
        timer = asyncio.ensure_future(asyncio.sleep(t / 1000))
        done, pending = await asyncio.wait(
            [task, timer], return_when=asyncio.FIRST_COMPLETED
        )
        for p in pending:
            p.cancel()
        if task in done:
            return task.result()
        raise Exception("Time Limit Exceeded")

    return wrapper
```
